    <style>
        /* 样式隔离，限定在 thinking-container 内 */
        .thinking-container {
            background-color: #fcfcfd;
            border: 1px solid #eceef1;
            border-radius: 12px;
            margin: 8px 0;
            max-width: 90%;
            font-family: 'Nunito', 'Quicksand', 'Varela Round', 'PingFang SC', 'Microsoft YaHei', sans-serif;
            color: #666666;
            overflow: hidden;
            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.02);
        }

        .thinking-summary {
            padding: 10px 14px;
            cursor: pointer;
            font-size: 0.85em;
            font-weight: 500;
            color: #8c8c8c;
            display: flex;
            align-items: center;
            justify-content: space-between;
            transition: background-color 0.2s ease;
            user-select: none;
            -webkit-tap-highlight-color: transparent;
        }

        .thinking-summary:hover {
            background-color: #f5f6f8;
        }

        .thinking-title-left {
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .thinking-arrow {
            transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
            font-size: 0.8em;
            opacity: 0.6;
        }

        /* 展开状态下的箭头旋转 */
        .thinking-container.expanded .thinking-arrow {
            transform: rotate(180deg);
        }

        /* 利用 CSS Grid 实现丝滑的展开/收起动画 */
        .thinking-content-wrapper {
            display: grid;
            grid-template-rows: 0fr;
            transition: grid-template-rows 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .thinking-container.expanded .thinking-content-wrapper {
            grid-template-rows: 1fr;
        }

        .thinking-content {
            overflow: hidden;
        }

        .thinking-inner {
            padding: 0 14px 14px 14px;
            font-size: 0.85em;
            line-height: 1.6;
            white-space: pre-wrap;
            border-top: 1px solid #eceef1;
            margin-top: 4px;
            padding-top: 10px;
        }
    </style>

    <div class="thinking-container">
        <!-- 点击触发父元素的 expanded 类名切换 -->
        <div class="thinking-summary" onclick="this.parentElement.classList.toggle('expanded')">
