<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
</head>
<body>
    <style>
        /* --- 复古档案风/书籍排版 CSS (V4 首行缩进版) --- */
        .archive-header-wrapper {
            /* 柔和的渐显入场动效 */
            animation: archiveFadeIn 0.8s ease-out forwards;
            /* 底部宽敞留白，自然过渡到正文 */
            margin-bottom: 35px;
            display: flex;
            flex-direction: column;
            /* 继承酒馆文字颜色，确保自适应主题 */
            color: var(--SmartThemeBodyColor, inherit);
            background: transparent;
            box-sizing: border-box;
            width: 100%;
            /* 强制使用衬线体家族，营造印刷感 */
            font-family: "Songti SC", "Noto Serif CJK SC", "SimSun", "Times New Roman", serif;
        }

        /* 顶部小字信息（时间/地点/编号） */
        .archive-info {
            font-size: 0.75em;
            text-transform: uppercase;
            letter-spacing: 2px;
            margin-bottom: 8px;
            opacity: 0.8;
            font-weight: 600;
        }

        /* 粗分割线 */
        .archive-line-thick {
            height: 2px;
            background-color: currentColor;
            margin-bottom: 18px;
            opacity: 0.85;
        }

        /* 细分割线 */
        .archive-line-thin {
            height: 1px;
            background-color: currentColor;
            margin-top: 18px;
            opacity: 0.4;
        }

        /* 英文副标题 */
        .archive-title-en {
            font-size: 1.25em;
            letter-spacing: 1.5px;
            text-transform: uppercase;
            margin-bottom: 4px;
        }

        /* 中文大标题 */
        .archive-title-cn {
            font-size: 1.9em;
            font-weight: bold;
            letter-spacing: 2px;
            line-height: 1.2;
        }

        /* 引言容器：轻微缩进 */
        .archive-quote-container {
            margin-left: 12%;
            margin-top: 15px;
            display: flex;
            flex-direction: column;
            max-width: 85%;
        }

        /* 引言文本 */
        .archive-quote-text {
            font-size: 0.85em;
            line-height: 1.8;
            opacity: 0.75;
            text-align: justify;
            /* 核心修改：首行缩进两字符 */
            text-indent: 2em;
        }

        /* 手机端响应式适配 */
        @media screen and (max-width: 600px) {
            .archive-header-wrapper {
                margin-bottom: 25px;
            }
            .archive-title-cn {
                font-size: 1.6em;
            }
            .archive-title-en {
                font-size: 1.1em;
            }
            .archive-quote-container {
                margin-left: 5%;
                max-width: 95%;
            }
        }

        /* 渐隐渐显上浮动画 */
        @keyframes archiveFadeIn {
            0% {
                opacity: 0;
                transform: translateY(10px);
            }
            100% {
                opacity: 1;
                transform: translateY(0);
            }
        }
    </style>

    <div class="archive-header-wrapper">
        <!-- $1 映射：Info 时间地点档案号 -->
        <div class="archive-info">$1</div>
        <!-- 顶部粗线 -->
        <div class="archive-line-thick"></div>

        <!-- $2 映射：TitleEN 英文标题 -->
        <div class="archive-title-en">$2</div>
        <!-- $3 映射：TitleCN 中文大标题 -->
        <div class="archive-title-cn">$3</div>

        <!-- 底部细线 -->
        <div class="archive-line-thin"></div>

        <!-- 轻微右移的引言区域 -->
        <div class="archive-quote-container">
            <!-- $4 映射：Quote 引言（已去除双引号，配合首行缩进） -->
            <div class="archive-quote-text">$4</div>
        </div>
    </div>
</body>
</html>
