    <style>
        @import url('https://fonts.googleapis.com/css2?family=Rajdhani:wght@600;700&family=Noto+Sans+SC:wght@400;700;900&family=Playfair+Display:ital,wght@0,400;0,700;1,400&family=LXGW+WenKai:wght@400;700&family=Zen+Maru+Gothic:wght@400;500&display=swap');
    </style>
</head>
<body>
    <style>
        .ap-root * { margin: 0; padding: 0; box-sizing: border-box; }
        .ap-root {
            width: 100%;
            max-width: 420px;
            margin: 10px auto;
            position: relative;
            transition: all 0.35s ease;
        }

        /* ══════════════════════════════════════
           P5R ── 斜切黑红 (明暗优化版)
           ══════════════════════════════════════ */
        .ap-root.ap-p5r {
            /* 调整为软黑、正红、柔和白，降低刺眼感 */
            --p-bk: #141414;
            --p-rd: #e60012;
            --p-wh: #dcdcdc;
            --p-gr: #7a7a7a;
            font-family: 'Rajdhani', 'Noto Sans SC', sans-serif;
            font-weight: 700;
        }
        .ap-root.ap-p5r .ap-shell {
            background: var(--p-bk);
            border: 2px solid var(--p-rd);
            padding: 12px 12px 8px;
            position: relative;
            overflow: hidden;
            clip-path: polygon(0 0, calc(100% - 20px) 0, 100% 20px, 100% 100%, 20px 100%, 0 calc(100% - 20px));
        }
        .ap-root.ap-p5r .ap-shell::before {
            content: '';
            position: absolute;
            top: -60%;
            right: -25%;
            width: 50%;
            height: 220%;
            background: repeating-linear-gradient(
                -45deg,
                transparent, transparent 7px,
                rgba(230, 0, 18, 0.08) 7px, rgba(230, 0, 18, 0.08) 9px
            );
            pointer-events: none;
            animation: ap5-stripe 22s linear infinite;
        }
        @keyframes ap5-stripe {
            0% { transform: translateY(0); }
            100% { transform: translateY(50%); }
        }

        /* P5R 顶栏 */
        .ap-root.ap-p5r .ap-head {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding-bottom: 8px;
            margin-bottom: 8px;
            border-bottom: 1px solid rgba(230, 0, 18, 0.4);
        }
        .ap-root.ap-p5r .ap-head-title {
            font-family: 'Rajdhani', sans-serif;
            font-size: 0.65em;
            font-weight: 700;
            letter-spacing: 5px;
            color: var(--p-rd);
            text-transform: uppercase;
            transform: skewX(-8deg);
        }

        /* P5R 选项 */
        .ap-root.ap-p5r .ap-list { display: flex; flex-direction: column; gap: 5px; }
        .ap-root.ap-p5r .ap-item {
            display: flex;
            align-items: stretch;
            cursor: pointer;
            position: relative;
            overflow: hidden;
            background: #1c1c1c;
            border: 1px solid rgba(230, 0, 18, 0.3);
            transform: skewX(-3deg);
            transition: all 0.15s ease;
            user-select: none;
        }
        .ap-root.ap-p5r .ap-item::after {
            content: '';
            position: absolute;
            inset: 0;
            background: var(--p-rd);
            transform: translateX(-105%);
            transition: transform 0.28s cubic-bezier(0.22, 1, 0.36, 1);
            z-index: 0;
        }
        .ap-root.ap-p5r .ap-item:hover::after { transform: translateX(0); }
        .ap-root.ap-p5r .ap-item:hover { border-color: var(--p-rd); }
        .ap-root.ap-p5r .ap-item:active { transform: skewX(-3deg) scale(0.97); }

        .ap-root.ap-p5r .ap-key {
            width: 28px; min-width: 28px;
            display: flex; align-items: center; justify-content: center;
            font-family: 'Rajdhani', sans-serif;
            font-size: 0.85em; font-weight: 700;
            color: #fff; /* 标签上的字可以白一点，因为底色是红的 */
            background: var(--p-rd);
            transform: skewX(3deg);
            position: relative; z-index: 1;
        }
        .ap-root.ap-p5r .ap-val {
            padding: 7px 10px;
            font-family: 'Noto Sans SC', sans-serif;
            font-size: 0.75em; font-weight: 700;
            line-height: 1.55;
            color: var(--p-wh); /* 柔和白 */
            position: relative; z-index: 1;
            transform: skewX(3deg);
            white-space: pre-wrap;
            transition: color 0.2s ease;
        }

        /* Hover时文字变白，因为底色变成了红色 */
        .ap-root.ap-p5r .ap-item:hover .ap-val {
            color: #fff;
        }

        .ap-root.ap-p5r .ap-divider {
            display: flex; align-items: center; gap: 6px;
            margin: 2px 0;
            color: var(--p-gr);
            font-family: 'Rajdhani', sans-serif;
            font-size: 0.55em; font-weight: 600;
            letter-spacing: 3px;
            transform: skewX(-3deg);
        }
        .ap-root.ap-p5r .ap-divider::before,
        .ap-root.ap-p5r .ap-divider::after {
            content: ''; flex: 1; height: 1px;
            background: linear-gradient(90deg, transparent, rgba(230,0,18,0.4), transparent);
        }

        /* 彻底移除紫色，E选项改为黑红反转的特殊样式 */
        .ap-root.ap-p5r .ap-item[data-k="E"] .ap-key {
            background: #2a2a2a;
            color: var(--p-rd);
            border-right: 1px solid var(--p-rd);
        }
        .ap-root.ap-p5r .ap-item[data-k="E"] .ap-val {
            color: #e87a85; /* 略带红晕的灰色，区分普通选项 */
        }
        .ap-root.ap-p5r .ap-item[data-k="E"]:hover .ap-key {
            color: #fff;
            background: transparent;
        }

        .ap-root.ap-p5r .ap-item[data-k="F"] .ap-key { background: #333; }
        .ap-root.ap-p5r .ap-item[data-k="F"] { opacity: 0.65; }


        /* ══════════════════════════════════════
           古杂志 ── 复古印刷
           ══════════════════════════════════════ */
        .ap-root.ap-mag {
            font-family: 'LXGW WenKai', 'Playfair Display', serif;
        }
        .ap-root.ap-mag .ap-shell {
            background: #f3ebd4;
            background-image:
                radial-gradient(ellipse at 15% 45%, rgba(150, 120, 70, 0.07) 0%, transparent 65%),
                radial-gradient(ellipse at 85% 25%, rgba(130, 100, 60, 0.05) 0%, transparent 55%);
            border: 3px double #8b7355;
