        .ap-root.ap-mag .ap-shell::before,
        .ap-root.ap-mag .ap-shell::after {
            position: absolute;
            font-size: 16px;
            color: #a08a60;
            opacity: 0.45;
            pointer-events: none;
        }
        .ap-root.ap-mag .ap-shell::before { content: '❧'; top: 3px; left: 7px; }
        .ap-root.ap-mag .ap-shell::after { content: '❧'; bottom: 3px; right: 7px; transform: rotate(180deg); }

        .ap-root.ap-mag .ap-head {
            display: flex; justify-content: space-between; align-items: center;
            padding-bottom: 7px; margin-bottom: 8px;
            border-bottom: 1px solid #c4a97d;
        }
        .ap-root.ap-mag .ap-head-title {
            font-family: 'Playfair Display', serif;
