        }
        .ap-root.ap-mag .ap-head-title::before { content: '§ '; }
        .ap-root.ap-mag .ap-head-title::after { content: ' §'; }

        .ap-root.ap-mag .ap-list { display: flex; flex-direction: column; gap: 3px; }
        .ap-root.ap-mag .ap-item {
            display: flex; align-items: stretch;
