        }
        .ap-root.ap-mag .ap-divider::before { content: '— ✦ '; }
        .ap-root.ap-mag .ap-divider::after { content: ' ✦ —'; }

        .ap-root.ap-mag .ap-item[data-k="E"] .ap-val { color: #6b4226; font-style: italic; }
        .ap-root.ap-mag .ap-item[data-k="F"] { opacity: 0.6; }


        /* ══════════════════════════════════════
           樱 ── 和纸与落花
           ══════════════════════════════════════ */
        .ap-root.ap-skr {
            font-family: 'Zen Maru Gothic', 'Noto Sans SC', sans-serif;
            font-weight: 500;
        }
        .ap-root.ap-skr .ap-shell {
            background: #faf6f1;
            background-image:
                radial-gradient(ellipse at 80% 10%, rgba(240, 180, 190, 0.12) 0%, transparent 50%),
                radial-gradient(ellipse at 10% 90%, rgba(180, 210, 180, 0.08) 0%, transparent 45%);
            border: 1px solid #e6d6cc;
