        /* 和纸纹理覆盖 */
        .ap-root.ap-skr .ap-shell::before {
            content: '';
            position: absolute;
            inset: 0;
            background:
                repeating-linear-gradient(
                    0deg,
                    transparent, transparent 3px,
                    rgba(180, 140, 120, 0.018) 3px, rgba(180, 140, 120, 0.018) 4px
                ),
                repeating-linear-gradient(
