        if (typeof window.apPick !== 'function') {
            window.apPick = function(el) {
                var textNode = el.querySelector('.ap-val');
                var content = textNode ? textNode.innerText.trim() : '';
                if (!content) return;

                // 优先尝试使用 triggerSlash 调用 /setinput 命令
                var triggerFn = window.parent.triggerSlash || window.triggerSlash;
                if (typeof triggerFn === 'function') {
                    // 构建 STscript 命令，使用 /setinput 填入输入框
                    var command = '/setinput ' + content;
                    triggerFn(command);
                } else {
                    // Fallback：如果 triggerSlash 不可用，尝试直接操作父窗口的 DOM
                    var ta = window.parent.document.querySelector('#send_textarea') || document.querySelector('#send_textarea');
                    if (ta) {
                        ta.value = content;
                        ta.dispatchEvent(new Event('input', { bubbles: true }));
                        ta.focus();
                    }
                }

                el.style.opacity = '0.45';
                setTimeout(function() { el.style.opacity = ''; }, 280);
                apToast('已填入输入框');
            };
        }

        if (typeof window.apTheme !== 'function') {
            window.apTheme = function(btn, name) {
                var root = btn.closest('.ap-root');
                if (!root) return;
                root.className = 'ap-root ap-' + name;
                var dots = root.querySelectorAll('.ap-sw-btn');
                for (var i = 0; i < dots.length; i++) dots[i].classList.remove('is-on');
                btn.classList.add('is-on');
                try { localStorage.setItem('ap-theme-pref', name); } catch(e) {}
            };
        }

        if (typeof window.apToast !== 'function') {
            window.apToast = function(msg) {
                var t = document.getElementById('ap-global-toast');
                if (!t) {
                    t = document.createElement('div');
                    t.id = 'ap-global-toast';
                    t.style.cssText = 'position:fixed;top:14px;left:50%;transform:translateX(-50%) translateY(-35px);padding:4px 16px;border-radius:12px;font-size:0.7em;color:#fff;background:rgba(25,25,25,0.85);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);opacity:0;transition:all 0.25s ease;z-index:99999;pointer-events:none;';
                    document.body.appendChild(t);
                }
                t.textContent = msg;
                t.style.opacity = '1';
                t.style.transform = 'translateX(-50%) translateY(0)';
                clearTimeout(t._h);
                t._h = setTimeout(function() {
                    t.style.opacity = '0';
                    t.style.transform = 'translateX(-50%) translateY(-35px)';
                }, 1100);
            };
        }

        (function() {
            var saved = '';
            try { saved = localStorage.getItem('ap-theme-pref'); } catch(e) {}
            if (!saved) return;
            var panels = document.querySelectorAll('.ap-root:not([data-ap-init])');
            for (var i = 0; i < panels.length; i++) {
                var p = panels[i];
                p.className = 'ap-root ap-' + saved;
                p.setAttribute('data-ap-init', '1');
                var dots = p.querySelectorAll('.ap-sw-btn');
                for (var j = 0; j < dots.length; j++) {
                    dots[j].classList.remove('is-on');
                    if (dots[j].classList.contains('ap-sw-' + saved)) dots[j].classList.add('is-on');
                }
            }
        })();
    </script>
</body>
</html>
