    <script>
        (function() {
            const currentScript = document.currentScript;
            const container = currentScript.parentElement;

            const dataSource = container.querySelector('.nsfw-log-data-source').innerText || '';
            const cleanSource = dataSource.replace(/^[\s\S]*<\/(?:think|thinking)>/i, '').trim();

            const extractTag = (tag, text) => {
                const reg = new RegExp(`<${tag}>([\\s\\S]*?)<\\/${tag}>`, 'i');
                const match = text.match(reg);
                return match ? match[1].trim() : '-';
            };

            const data = {
                round: extractTag('Round', cleanSource),
                phase: extractTag('Phase', cleanSource),
                location: extractTag('Location', cleanSource),
                posture: extractTag('Posture', cleanSource),
                play: extractTag('Play', cleanSource),
                intensity: parseInt(extractTag('Intensity', cleanSource)) || 0,
                historyRaw: extractTag('History', cleanSource)
            };

            const clothingRaw = extractTag('Clothing', cleanSource);
            data.clothingActive = extractTag('主动方', clothingRaw);
            data.clothingPassive = extractTag('被动方', clothingRaw);

            // 更新头部摘要信息
            container.querySelector('#nsfw-log-summary').innerText = `R${data.round} : I${data.intensity}`;

            // 构建核心参数列表
            const paramsHtml = `
                <div class="nsfw-log-label">Round</div><div class="nsfw-log-value">${data.round}</div>
                <div class="nsfw-log-label">Phase</div><div class="nsfw-log-value">${data.phase}</div>
                <div class="nsfw-log-label">Location</div><div class="nsfw-log-value">${data.location}</div>
                <div class="nsfw-log-label">Posture</div><div class="nsfw-log-value">${data.posture}</div>
                <div class="nsfw-log-label">Play</div><div class="nsfw-log-value">${data.play}</div>
                <div class="nsfw-log-label">Clothing A</div><div class="nsfw-log-value">${data.clothingActive}</div>
                <div class="nsfw-log-label">Clothing P</div><div class="nsfw-log-value">${data.clothingPassive}</div>
                <div class="nsfw-log-label">Intensity</div>
                <div class="nsfw-log-value nsfw-log-intensity-wrapper">
                    <div class="nsfw-log-bar-track">
                        <div class="nsfw-log-bar-fill" style="width: ${Math.min((data.intensity / 10) * 100, 100)}%;"></div>
                    </div>
                </div>
            `;
            container.querySelector('#nsfw-log-params-inject').innerHTML = paramsHtml;

            // 解析历史表格
            const parseHistory = (mdText) => {
                if (mdText === '-') return '';
                const lines = mdText.split('\n').map(l => l.trim()).filter(l => l.startsWith('|') && l.endsWith('|'));
                if (lines.length === 0) return '';

                let tableHtml = '';
                lines.forEach((line, index) => {
                    if (/^[|\-\s:]+$/.test(line)) return;
                    const cells = line.split('|').slice(1, -1).map(c => c.trim());
                    if (cells.length === 0) return;

                    let rowHtml = '<tr>';
                    cells.forEach(cell => {
                        rowHtml += index === 0 ? `<th>${cell}</th>` : `<td>${cell}</td>`;
                    });
                    rowHtml += '</tr>';
                    tableHtml += rowHtml;
                });
                return tableHtml;
            };

            container.querySelector('#nsfw-log-table-inject').innerHTML = parseHistory(data.historyRaw);

            // 绑定全局展开/收起交互
            const headerBtn = container.querySelector('#nsfw-log-header-btn');
            const bodyArea = container.querySelector('#nsfw-log-body-area');
            const toggleIcon = container.querySelector('#nsfw-log-icon');

            headerBtn.addEventListener('click', () => {
                const isOpen = bodyArea.classList.contains('is-open');
                if (isOpen) {
                    bodyArea.classList.remove('is-open');
                    toggleIcon.innerText = '[+]';
                } else {
                    bodyArea.classList.add('is-open');
                    toggleIcon.innerText = '[-]';
                }
            });
        })();
    </script>
</body>
