scripts.content:
const KEY = 'preset_switchboard';
const clone = x => JSON.parse(JSON.stringify(x));
function order(p) {
  const o = p.prompt_order?.find(x => x.character_id === 100001);
  if (!o) throw Error('预设缺少聊天补全提示词顺序，暂不支持此格式');
  return o.order;
}
function enabled(p, id) { return order(p).find(x => x.identifier === id)?.enabled === true; }
// Preserve the exact native order even when a category spans separated sections.
function displayGroups(p, c) {
  const byId=new Map(p.prompts.map(x=>[x.identifier,x])), membership=new Map();
  c.groups.forEach(g=>g.ids.forEach(id=>membership.set(id,g)));
  const listed=new Set(), sequence=[];
  for(const row of order(p)) if(byId.has(row.identifier)&&!listed.has(row.identifier)){listed.add(row.identifier);sequence.push(row.identifier);}
  for(const x of p.prompts) if(!listed.has(x.identifier))sequence.push(x.identifier);
  const groups=[], seen=new Set();
  for(const id of sequence){
    const g=membership.get(id)||{id:'other',name:c.otherName||'其他条目',description:''};
    if(groups.at(-1)?.id===g.id)groups.at(-1).ids.push(id);
    else {groups.push({...g,name:g.name+(seen.has(g.id)?' · 续':''),ids:[id]});seen.add(g.id);}
  }
  return groups;
}
function validate(p, c, allowMissing = false) {
  if (c?.version !== 1 || !c.id || !Array.isArray(c.groups) || !Array.isArray(c.questions)) throw Error('配置格式不正确');
  const ids = new Set(p.prompts.map(x => x.identifier));
  if (ids.size !== p.prompts.length) throw Error('预设存在重复条目 ID');
  const deleted = p.extensions?.[KEY]?.state?.trash || [];
  deleted.forEach(x => ids.add(x.prompt.identifier));
  const check = list => { if (!Array.isArray(list) || list.some(id => typeof id !== 'string' || (!allowMissing && !ids.has(id)))) throw Error('配置引用了不存在的条目'); };
  const assigned = new Set(), groupIds = new Set();
  c.groups.forEach(g => {
    if (!g.id || groupIds.has(g.id) || typeof g.name !== 'string') throw Error('分组标识必须唯一');
    groupIds.add(g.id); check(g.ids);
    g.ids.forEach(id => { if (assigned.has(id)) throw Error('条目不能重复分组'); assigned.add(id); });
  });
  check(c.protected || []);
  (c.exclusive || []).forEach(check);
  for (const group of c.exclusive || []) if (group.length < 2 || new Set(group).size !== group.length) throw Error('互斥组至少需要两个不同条目');
  if (c.descriptions && (typeof c.descriptions !== 'object' || Array.isArray(c.descriptions))) throw Error('条目说明格式错误');
  for (const [id, text] of Object.entries(c.descriptions || {})) { check([id]); if (typeof text !== 'string') throw Error('说明必须是文字'); }
  if (c.requires && (typeof c.requires !== 'object' || Array.isArray(c.requires))) throw Error('依赖配置格式错误');
  for (const [id, deps] of Object.entries(c.requires || {})) { check([id]); check(deps); }
  const visiting = new Set(), visited = new Set();
  function visit(id) {
    if (visiting.has(id)) throw Error('存在循环依赖，请移除相互依赖的连线');
    if (visited.has(id)) return;
    visiting.add(id); (c.requires?.[id] || []).forEach(visit); visiting.delete(id); visited.add(id);
  }
  Object.keys(c.requires || {}).forEach(visit);
  function dependencies(id, set = new Set()) { set.add(id); for (const dep of c.requires?.[id] || []) if (!set.has(dep)) dependencies(dep, set); return set; }
  for (const id of Object.keys(c.requires || {})) {
    const needed = dependencies(id);
    if ((c.exclusive || []).some(g => g.filter(x => needed.has(x)).length > 1)) throw Error('依赖链包含互斥条目，无法同时开启');
  }
  const qids = new Set();
  c.questions.forEach(q => {
    if (!q.id || qids.has(q.id) || !Array.isArray(q.options)) throw Error('问题格式错误');
    qids.add(q.id);
    if (!q.title?.trim() || !q.options.length) throw Error('问题需要标题和至少一个答案');
    q.options.forEach(o => {
      check(o.on || []); check(o.off || []);
      if (!o.label?.trim()) throw Error('答案名称不能为空');
      const needed = new Set((o.on || []).flatMap(id => [...dependencies(id)]));
      if ((o.off || []).some(id => needed.has(id))) throw Error('同一答案不能关闭它需要开启的条目');
      if ((c.exclusive || []).some(g => g.filter(x => needed.has(x)).length > 1)) throw Error('同一答案不能开启互斥条目');
    });
  });
  return c;
}
function initialize(p) {
  const box = p.extensions?.[KEY];
  if (!box) throw Error('当前预设没有管家配置');
  validate(p, box.config, true);
  box.state ||= { initialized: false, compact: true, floating: false, favorites: [], open: [], trash: [], baseline: { prompts: clone(p.prompts), prompt_order: clone(p.prompt_order) } };
  box.state.profiles ||= [];
  return box;
}
function applySwitches(p, turnOn, turnOff, config) {
  const on = new Set(turnOn), off = new Set(turnOff);
  const label = id => p.prompts.find(x => x.identifier === id)?.name || id;
  function need(id) { for (const dep of config.requires?.[id] || []) if (!on.has(dep)) { on.add(dep); need(dep); } }
  [...on].forEach(need);
  for (const group of config.exclusive || []) {
    const chosen = group.filter(id => on.has(id));
    if (chosen.length > 1) throw Error('选择冲突：'+chosen.map(label).join('、')+' 不能同时开启');
    if (chosen.length) group.filter(id => id !== chosen[0]).forEach(id => off.add(id));
  }
  // Turning off or deleting a prerequisite also turns off its enabled dependents.
  let changed = true;
  while (changed) {
    changed = false;
    for (const [id, deps] of Object.entries(config.requires || {})) {
      if (!off.has(id) && deps.some(dep => off.has(dep))) { off.add(id); changed = true; }
    }
  }
  const clash = [...on].filter(id => off.has(id));
  if (clash.length) throw Error('选择与依赖冲突：'+clash.map(label).join('、')+' 被同时要求开启和关闭');
  for (const [ids, value] of [[off, false], [on, true]]) for (const id of ids) {
    const row = order(p).find(x => x.identifier === id);
    if (!row) { if (value) throw Error('需要的条目不在使用列表，请先恢复：'+label(id)); continue; }
    if (enabled(p, id) !== value && (config.protected || []).includes(id)) throw Error('联动涉及受保护的基础条目：'+label(id));
    if (enabled(p, id) === value) continue;
    row.enabled = value;
    const prompt = p.prompts.find(x => x.identifier === id);
    if (prompt) prompt.enabled = value;
  }
}
function issues(p) {
  const c = p.extensions?.[KEY]?.config;
  if (!c) return [];
  const label = id => p.prompts.find(x => x.identifier === id)?.name || p.extensions[KEY].state?.trash?.find(x=>x.prompt.identifier===id)?.prompt.name || id;
  const result = [];
  for (const group of c.exclusive || []) {
    const active = group.filter(id => enabled(p, id));
    if (active.length > 1) result.push('互斥项同时开启：'+active.map(label).join('、'));
  }
  for (const [id, deps] of Object.entries(c.requires || {})) if (enabled(p,id)) {
    const missing = deps.filter(dep => !enabled(p,dep));
    if (missing.length) result.push(label(id)+' 需要开启：'+missing.map(label).join('、'));
  }
  return result;
}
function differences(before, after) {
  const rows = [];
  const a = new Map(before.prompts.map(x=>[x.identifier,x])), b = new Map(after.prompts.map(x=>[x.identifier,x]));
  for (const [id, prompt] of a) {
    if (!b.has(id)) rows.push({ id, name: prompt.name, kind: '移入回收站' });
    else if (enabled(before,id) !== enabled(after,id)) rows.push({ id, name: b.get(id).name, kind: enabled(after,id)?'开启':'关闭' });
    else if (JSON.stringify(prompt) !== JSON.stringify(b.get(id))) rows.push({id, name: b.get(id).name, kind:'还原内容'});
  }
  for (const [id, prompt] of b) if (!a.has(id)) rows.push({id,name:prompt.name,kind:enabled(after,id)?'恢复并开启':'恢复'});
  return rows;
}
function mutate(source, action) {
  const p = clone(source), { config, state } = initialize(p);
  const id = action.id;
  if (action.type === 'toggle') applySwitches(p, action.value?[id]:[], action.value?[]:[id], config);
  else if (action.type === 'answers') {
    const on = [], off = [];
    for (const q of config.questions) {
      const i = action.answers[q.id];
      if (i === '' || i === undefined) continue;
      const option = q.options[Number(i)];
      if (!option) throw Error('无效选项');
      on.push(...option.on || []); off.push(...option.off || []);
    }
    applySwitches(p,on,off,config);
    state.initialized = true; state.compact = true; state.open = [];
  } else if (action.type === 'delete') {
    if ((config.protected || []).includes(id)) throw Error('基础条目受保护');
    const index = p.prompts.findIndex(x => x.identifier === id);
    if (index < 0) throw Error('条目已经删除');
    state.trash.push({ prompt: p.prompts[index], index, before: p.prompts[index+1]?.identifier, positions: p.prompt_order.map(profile => ({ character_id: profile.character_id, index: profile.order.findIndex(x => x.identifier === id), row: profile.order.find(x => x.identifier === id), before: profile.order[profile.order.findIndex(x => x.identifier === id) + 1]?.identifier })) });
    state.trash[state.trash.length-1] = clone(state.trash[state.trash.length-1]);
    applySwitches(p, [], [id], config);
    p.prompts.splice(index, 1);
    p.prompt_order.forEach(o => o.order = o.order.filter(x => x.identifier !== id));
  } else if (action.type === 'restore') {
    const items = state.trash.filter(x => !id || x.prompt.identifier === id);
    const turnOn = [];
    for (const item of [...items].reverse()) {
      if (p.prompts.some(x => x.identifier === item.prompt.identifier)) throw Error('存在同 ID 条目，请先处理冲突');
      const promptAnchor = p.prompts.findIndex(x => x.identifier === item.before);
      p.prompts.splice(promptAnchor >= 0 ? promptAnchor : Math.min(item.index, p.prompts.length), 0, item.prompt);
      for (const pos of item.positions) if (pos.row) {
        const profile = p.prompt_order.find(x => x.character_id === pos.character_id);
        if (!profile) throw Error('原提示词顺序已不存在');
        const anchor = profile.order.findIndex(x => x.identifier === pos.before);
        profile.order.splice(anchor >= 0 ? anchor : Math.min(pos.index, profile.order.length), 0, pos.row);
      }
      // Restoring a formerly enabled alternative must keep exclusivity intact.
      if (enabled(p, item.prompt.identifier)) turnOn.push(item.prompt.identifier);
    }
    applySwitches(p,turnOn,[],config);
    state.trash = state.trash.filter(x => !items.includes(x));
  } else if (action.type === 'reset') {
    p.prompts = clone(state.baseline.prompts); p.prompt_order = clone(state.baseline.prompt_order);
    state.trash = []; state.compact = false; state.open = config.groups.map(g => g.id);
  } else if (action.type === 'profile-save') {
    const name = String(action.name || '').trim();
    if (!name || name.length > 60) throw Error('方案名称需要 1 至 60 个字');
    if (!action.id || state.profiles.some(x=>x.name===name && x.id!==action.id)) throw Error('方案名称已存在，请改名或选择覆盖');
    const profile = {id:action.id,name,switches:order(p).filter(x=>!(config.protected||[]).includes(x.identifier)).map(x=>({id:x.identifier,enabled:!!x.enabled}))};
    const index=state.profiles.findIndex(x=>x.id===action.id);
    if(index<0)state.profiles.push(profile);else state.profiles[index]=profile;
  } else if (action.type === 'profile-load') {
    const profile=state.profiles.find(x=>x.id===id);
    if(!profile)throw Error('方案不存在');
    const available=new Set(order(p).map(x=>x.identifier));
    if(profile.switches.some(x=>!available.has(x.id)))throw Error('方案中的条目已被删除或移出列表，请先恢复条目，或保存新的方案');
    const switches=profile.switches.filter(x=>!(config.protected||[]).includes(x.id));
    applySwitches(p,switches.filter(x=>x.enabled).map(x=>x.id),switches.filter(x=>!x.enabled).map(x=>x.id),config);
    state.compact=true;state.open=[];
  } else if (action.type === 'profile-delete') {
    if(!state.profiles.some(x=>x.id===id))throw Error('方案不存在');
    state.profiles=state.profiles.filter(x=>x.id!==id);
  } else if (action.type === 'group-rename') {
    const name=String(action.name||'').trim();if(!name||name.length>40)throw Error('分组名称需要 1 至 40 个字');
    if(id==='other')config.otherName=name;
    else {const group=config.groups.find(x=>x.id===id);if(!group)throw Error('分组不存在');group.name=name;}
  } else if (action.type === 'group-move') {
    if(!p.prompts.some(x=>x.identifier===id))throw Error('条目已不存在，请刷新');
    const target=action.group==='other'?null:config.groups.find(x=>x.id===action.group);
    if(action.group!=='other'&&!target)throw Error('目标分组不存在');
