    const before = clone(current());
    try {
      const next = nextFor(before,action);
      const list = manager.getPresetList(), slot = list.preset_names[name];
      if (slot === undefined || !list.presets[slot]) throw Error('找不到当前预设的保存位置');
      // Preserve provider/model settings and every foreign extension verbatim.
      const disk = clone(list.presets[slot]);
      disk.prompts = clone(next.prompts); disk.prompt_order = clone(next.prompt_order);
      disk.extensions ||= {}; disk.extensions[KEY] = clone(next.extensions[KEY]);
      await manager.savePreset(name, disk, { skipUpdate: true });
      Object.assign(list.presets[slot], disk);
      if (!active()) return;
      const live = rawCurrent();live.extensions ||= {};
      if(JSON.stringify(live.prompts)!==JSON.stringify(before.prompts)||JSON.stringify(live.prompt_order)!==JSON.stringify(before.prompt_order)) {
        throw Error('文件已保存，但当前提示词在保存期间发生变化；已保留当前编辑，请检查后重试。');
      }
      live.prompts = clone(next.prompts); live.prompt_order = clone(next.prompt_order);
      live.extensions[KEY] = clone(next.extensions[KEY]);
      ctx.saveSettingsDebounced();
      if (keepUndo) undo = action.type === 'undo' ? null : before;
      status = (action.type === 'ui'||action.type.startsWith('group-')) ? '显示设置已保存。' : action.type==='config'?'作者配置已保存。':action.type.startsWith('profile-')&&action.type!=='profile-load'?'方案已保存。':'已保存，下次生成使用当前开关。';
      try { promptManager?.render?.(false); } catch { status += '原生列表请重新打开查看。'; }
