      else if(a==='profile-overwrite') {const x=s.profiles.find(x=>x.id===id);review({type:'profile-save',id,name:x.name},'覆盖方案：'+x.name);return;}
      else if(a==='profile-delete') {review({type:'profile-delete',id},'删除方案：'+s.profiles.find(x=>x.id===id)?.name);return;}
