      else if(a==='skip'){await commit({type:'ui',patch:{initialized:true}},false);guide=false;}
      else if(a==='descriptions')await commit({type:'ui',patch:{showDescriptions:s.showDescriptions===false}},false);
      else if(a==='compact')await commit({type:'ui',patch:{compact:!s.compact}},false);
      else if(a==='expand')await commit({type:'ui',patch:{compact:false,open:[...box().config.groups.map(x=>x.id),'other','favorites']}},false);
      else if(a==='collapse')await commit({type:'ui',patch:{open:[]}},false);
      else if(a==='show-group')await commit({type:'ui',patch:{compact:false,open:[...new Set([...s.open,id])]}},false);
