      else if(a==='restore'||a==='restore-all'){review({type:'restore',id:a==='restore'?id:undefined},'恢复删除的条目');return;}
      else if(a==='undo'){review({type:'undo'},'撤销上一步');return;}
      else if(a==='reset'){review({type:'reset'},'恢复初始设置');return;}
